export const getMatrixCoefficientsFromIndex = (index) => {
    return index === 1
        ? 'bt709'
        : index === 5
            ? 'bt470bg'
            : index === 6
                ? 'smpte170m'
                : index === 9
                    ? 'bt2020'
                    : null;
};
export const getTransferCharacteristicsFromIndex = (index) => {
    return index === 1
        ? 'bt709'
        : index === 6
            ? 'smpte170m'
            : index === 13
                ? 'iec61966-2-1'
                : index === 18
                    ? 'arib-std-b67'
                    : null;
};
export const getPrimariesFromIndex = (index) => {
    return index === 1
        ? 'bt709'
        : index === 5
            ? 'bt470bg'
            : index === 6
                ? 'smpte170m'
                : index === 9
                    ? 'bt2020'
                    : null;
};
